<script>
(()=>{'use strict';
const $=id=>document.getElementById(id),form=$('pos-sale'),field=n=>form.elements.namedItem(n),catalog={{ \Illuminate\Support\Js::from($catalog) }},oldItems={{ \Illuminate\Support\Js::from(old('items',[])) }},quoteUrl={{ \Illuminate\Support\Js::from(route('business.admin.sales.retail-pos.quote',['business'=>request()->route('business')])) }},holdKey={{ \Illuminate\Support\Js::from('pos-hold-'.$business->id.'-'.$user->id) }},words={{ \Illuminate\Support\Js::from(['ambiguousBarcode'=>t('Multiple variants match. Select the correct variant from the catalog.','একাধিক ভ্যারিয়েন্ট পাওয়া গেছে। সঠিক ভ্যারিয়েন্ট নির্বাচন করুন।'),'empty'=>t('Your cart is empty','আপনার কার্ট খালি'),'noProducts'=>t('No matching products','কোনো পণ্য পাওয়া যায়নি'),'stock'=>t('Stock','স্টক'),'unlimited'=>t('Non-stock','স্টকবিহীন'),'out'=>t('Out of stock','স্টক নেই'),'limit'=>t('Stock or cart limit reached','স্টক অথবা কার্টের সীমা পূর্ণ'),'results'=>t('variants available','ভ্যারিয়েন্ট পাওয়া যাচ্ছে'),'clear'=>t('Clear current cart?','বর্তমান কার্ট মুছবেন?'),'held'=>t('Cart saved on this device.','এই ডিভাইসে কার্ট সংরক্ষিত।'),'replace'=>t('Replace the saved/current cart?','সংরক্ষিত/বর্তমান কার্ট বদলাবেন?'),'noHold'=>t('No held cart found.','হোল্ড করা কার্ট নেই।'),'storage'=>t('Local storage unavailable.','লোকাল স্টোরেজ পাওয়া যাচ্ছে না।'),'quoteError'=>t('Unable to verify the sale.','বিক্রয় যাচাই করা যায়নি।'),'customer'=>t('Select a registered customer for credit.','বাকির জন্য নিবন্ধিত কাস্টমার নির্বাচন করুন।'),'amount'=>t('Check the received amount.','গৃহীত টাকা যাচাই করুন।'),'checking'=>t('Verifying…','যাচাই হচ্ছে…'),'submitting'=>t('Posting sale…','বিক্রয় পোস্ট হচ্ছে…'),'review'=>t('Some saved quantities were adjusted to current stock.','বর্তমান স্টক অনুযায়ী কিছু পরিমাণ পরিবর্তন করা হয়েছে।'),'remove'=>t('Remove item','পণ্য সরান'),'quantity'=>t('Quantity','পরিমাণ'),'saleError'=>t('Sale could not be confirmed.','বিক্রয় নিশ্চিত করা যায়নি।'),'retry'=>t('Connection interrupted. Retry the same sale; do not start another sale.','সংযোগ বিচ্ছিন্ন। একই বিক্রয় পুনরায় চেষ্টা করুন; নতুন বিক্রয় শুরু করবেন না।'),'confirm'=>t('Confirm sale','বিক্রয় নিশ্চিত করুন'),'item'=>t('Item','পণ্য'),'total'=>t('Total','মোট'),'paid'=>t('Paid','পরিশোধিত'),'due'=>t('Due','বাকি'),'subtotal'=>t('Subtotal','সাবটোটাল'),'discount'=>t('Discount','ছাড়'),'tax'=>t('Tax / VAT','কর / ভ্যাট'),'receipt'=>t('Sales receipt','বিক্রয় রসিদ')]) }};
const products=new Map(catalog.map(p=>[String(p.id),p])),cart=new Map();let category='',limit=96,verified=null,busy=false,submitting=false;
const money=n=>'৳'+Number(n||0).toLocaleString('en-BD',{minimumFractionDigits:2,maximumFractionDigits:2}),round=n=>Math.round((n+Number.EPSILON)*100)/100,qtyRound=n=>Math.round(n*1000)/1000,maxQty=p=>p.stock===null?999999:Math.min(p.stock,999999);
function el(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e;}
function alertMsg(msg){$('pos-alert').textContent=msg;$('pos-alert').hidden=!msg;}
function photo(p,cls){const wrap=el('div',cls,'◇');if(p.image){const img=el('img');img.src=p.image;img.alt='';img.loading='lazy';img.addEventListener('error',()=>img.remove());wrap.append(img);}return wrap;}
function button(text,cls,cb){const b=el('button',cls,text);b.type='button';b.addEventListener('click',cb);return b;}
function filtered(){const term=$('pos-search').value.trim().toLowerCase();let rows=catalog.filter(p=>(!category||p.category===category)&&(!$('pos-stock-only').checked||maxQty(p)>0)&&[p.name,p.sku,p.productSku,p.variant,p.barcode,p.productBarcode].join(' ').toLowerCase().includes(term));const sort=$('pos-sort').value;return rows.sort((a,b)=>sort==='low'?a.price-b.price:sort==='high'?b.price-a.price:a.name.localeCompare(b.name));}
function renderProducts(){const rows=filtered(),holder=$('pos-products');holder.replaceChildren();$('pos-result').textContent=rows.length+' '+words.results;$('pos-more').hidden=rows.length<=limit;if(!rows.length)holder.append(el('div','pos-empty',words.noProducts));rows.slice(0,limit).forEach(p=>{const b=button('','pos-product',()=>add(p));b.disabled=maxQty(p)<=0;b.title=[p.name,p.variant,p.sku,p.barcode,p.productBarcode].filter(Boolean).join(' · ');const img=photo(p,'pos-photo');img.append(el('span','pos-stock',p.stock===null?words.unlimited:p.stock<=0?words.out:words.stock+': '+p.stock));const info=el('div','pos-product-info');info.append(el('div','pos-product-name',p.name),el('div','pos-product-meta',[p.variant,p.sku].filter(Boolean).join(' · ')));const bottom=el('div','pos-product-bottom');bottom.append(el('strong','',money(p.price)),el('span','pos-add','+'));info.append(bottom);b.append(img,info);holder.append(b);});}
function add(p){const id=String(p.id),qty=cart.get(id)||0;const next=Math.min(maxQty(p),qty+1);if(next<=qty||(!cart.has(id)&&cart.size>=100)){alertMsg(words.limit);return;}cart.set(id,qtyRound(next));alertMsg('');renderCart();}
function renderCart(){const holder=$('pos-cart');holder.replaceChildren();if(!cart.size)holder.append(el('div','pos-empty',words.empty));let i=0;for(const [id,qty] of cart){const p=products.get(id),row=el('div','pos-line');const img=photo(p,'pos-line-photo');const middle=el('div');middle.append(el('div','pos-line-name',p.name),el('div','pos-line-meta',[p.variant,p.sku,money(p.price)].filter(Boolean).join(' · ')));const controls=el('div','pos-qty');const change=n=>{if(n<=0)cart.delete(id);else cart.set(id,qtyRound(Math.min(maxQty(p),Math.max(.001,n))));renderCart();};const hidden=el('input');hidden.type='hidden';hidden.name=`items[${i}][variant_id]`;hidden.value=id;const input=el('input');input.type='number';input.name=`items[${i}][quantity]`;input.min='.001';input.max=String(maxQty(p));input.step='.001';input.value=qty;input.setAttribute('aria-label',words.quantity);input.addEventListener('change',()=>change(Number(input.value)||0));controls.append(hidden,button('−','',()=>change(qty-1)),input,button('+','',()=>change(qty+1)));middle.append(controls);const end=el('div','pos-line-end');end.append(el('strong','',money(round(p.price*qty))));const remove=button('×','',()=>{cart.delete(id);renderCart();});remove.setAttribute('aria-label',words.remove);end.append(remove);row.append(img,middle,end);holder.append(row);i++;}$('pos-count').textContent=cart.size;updateEstimate();}
function updateEstimate(){verified=null;const subtotal=round([...cart].reduce((s,[id,q])=>s+round(products.get(id).price*q),0));const discount=field('coupon_code').value.trim()?0:Math.min(subtotal,Math.max(0,Number(field('discount').value)||0));const base=round(subtotal-discount),opt=field('tax_id').selectedOptions[0],rate=Number(opt?.dataset.rate)||0,inclusive=opt?.dataset.inclusive==='1',tax=round(inclusive?base-base/(1+rate/100):base*rate/100);$('pos-subtotal').textContent=money(subtotal);$('pos-discount').textContent=field('coupon_code').value.trim()?'—':money(discount);$('pos-tax-total').textContent=money(tax);$('pos-total').textContent=money(base+(inclusive?0:tax));$('pos-checkout').disabled=!cart.size||busy;}
function setCustomer(){const guest=$('pos-guest');guest.hidden=!!field('customer_id').value;guest.disabled=guest.hidden;}
function restore(data){cart.clear();let changed=false;for(const row of Object.values(data.items||{})){const id=String(row.variant_id),p=products.get(id),q=Number(row.quantity);if(!p||!Number.isFinite(q)||q<=0||maxQty(p)<=0||cart.size>=100){changed=true;continue;}const next=qtyRound(Math.min(maxQty(p),q));if(next!==q)changed=true;cart.set(id,next);}for(const n of ['customer_id','customer_name','discount','coupon_code','tax_id'])if(data[n]!==undefined)field(n).value=data[n];setCustomer();renderCart();if(changed)alertMsg(words.review);}
function snapshot(){return {items:[...cart].map(([variant_id,quantity])=>({variant_id,quantity})),customer_id:field('customer_id').value,customer_name:field('customer_name').value,discount:field('discount').value,coupon_code:field('coupon_code').value,tax_id:field('tax_id').value};}
$('pos-hold').onclick=()=>{if(!cart.size)return;try{if(localStorage.getItem(holdKey)&&!confirm(words.replace))return;localStorage.setItem(holdKey,JSON.stringify(snapshot()));clearCart();alertMsg(words.held);}catch(e){alertMsg(words.storage);}};
$('pos-resume').onclick=()=>{try{const raw=localStorage.getItem(holdKey);if(!raw){alertMsg(words.noHold);return;}if(cart.size&&!confirm(words.replace))return;restore(JSON.parse(raw));localStorage.removeItem(holdKey);}catch(e){alertMsg(words.storage);}};
function clearCart(){cart.clear();for(const n of ['customer_id','customer_name','coupon_code','tax_id'])field(n).value='';field('discount').value='0';setCustomer();renderCart();}
$('pos-clear').onclick=()=>{if(cart.size&&confirm(words.clear))clearCart();};$('pos-theme')?.addEventListener('click',()=>window.SaasUITheme?.toggle());$('pos-search').oninput=()=>{limit=96;renderProducts();};$('pos-search').onkeydown=e=>{if(e.key!=='Enter')return;e.preventDefault();const term=e.target.value.trim().toLowerCase();if(!term)return;const eq=v=>String(v??'').toLowerCase()===term;const matches=catalog.filter(x=>eq(x.barcode)||eq(x.productBarcode)||eq(x.sku)||eq(x.productSku));if(matches.length===1){add(matches[0]);e.target.value='';renderProducts();}else if(matches.length>1){category='';for(const x of $('pos-categories').children)x.classList.toggle('active',!x.dataset.category);$('pos-stock-only').checked=false;renderProducts();alertMsg(words.ambiguousBarcode);}else alertMsg(words.noProducts);};$('pos-categories').onclick=e=>{const b=e.target.closest('[data-category]');if(!b)return;category=b.dataset.category;for(const x of $('pos-categories').children)x.classList.toggle('active',x===b);limit=96;renderProducts();};$('pos-stock-only').onchange=$('pos-sort').onchange=()=>{limit=96;renderProducts();};$('pos-more').onclick=()=>{limit+=96;renderProducts();};for(const n of ['discount','coupon_code','tax_id'])field(n).addEventListener('input',updateEstimate);field('customer_id').addEventListener('change',setCustomer);
async function checkout(){if(busy||!cart.size||!form.reportValidity())return;busy=true;$('pos-checkout').disabled=true;alertMsg(words.checking);try{const data=snapshot();const fingerprint=JSON.stringify(data);const res=await fetch(quoteUrl,{method:'POST',credentials:'same-origin',headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':field('_token').value},body:JSON.stringify(data)});const body=await res.json();if(!res.ok)throw Error(Object.values(body.errors||{}).flat()[0]||body.message||words.quoteError);if(fingerprint!==JSON.stringify(snapshot()))throw Error(words.review);verified=body;field('expected_total').value=Number(body.total).toFixed(2);field('payment_mode').value='full';field('payment_method').value='cash';field('payment_reference').value='';field('tendered').value=Number(body.total).toFixed(2);$('pos-pay-total').textContent=money(body.total);$('pos-pay-discount').textContent=money(body.discount);$('pos-pay-tax').textContent=money(body.tax);alertMsg('');$('pos-dialog').showModal();updatePayment();}catch(e){alertMsg(e.message||words.quoteError);}finally{busy=false;$('pos-checkout').disabled=!cart.size;}}
function updatePayment(){if(!verified)return;const total=Number(verified.total),mode=field('payment_mode').value,method=field('payment_method').value;if(mode==='due')field('tendered').value='0';field('tendered').readOnly=mode==='due';const received=Number(field('tendered').value),paid=mode==='due'?0:mode==='full'?Math.min(received,total):received;let msg='';if(!Number.isFinite(received)||received<0||(mode==='full'&&(received<total||(method==='bank'&&received!==total)))||(mode==='partial'&&(received<=0||received>=total)))msg=words.amount;else if(paid<total&&!field('customer_id').value)msg=words.customer;$('pos-change').textContent=money(mode==='full'&&method==='cash'?Math.max(0,received-total):0);$('pos-due').textContent=money(Math.max(0,total-paid));$('pos-pay-message').textContent=msg;$('pos-submit').disabled=!!msg||submitting;for(const b of $('pos-quick').children)b.disabled=mode==='due';}
for(const n of ['payment_mode','payment_method','tendered'])field(n).addEventListener('input',updatePayment);$('pos-quick').onclick=e=>{const b=e.target.closest('[data-cash]');if(!b||!verified)return;field('tendered').value=b.dataset.cash==='exact'?Number(verified.total).toFixed(2):b.dataset.cash;updatePayment();};$('pos-checkout').onclick=checkout;$('pos-close').onclick=()=>{if(!submitting&&!pendingSale)$('pos-dialog').close();};$('pos-dialog').addEventListener('cancel',e=>{if(submitting||pendingSale)e.preventDefault();});$('pos-dialog').addEventListener('close',()=>{verified=null;});
let pendingSale=null,lastReceiptUrl=null;
function freezePayment(lock){for(const n of ['payment_mode','payment_method','tendered','payment_reference'])field(n).disabled=lock;$('pos-close').disabled=lock;for(const b of $('pos-quick').children)b.disabled=lock;}
function showReceipt(receipt){const holder=$('pos-receipt-preview');holder.replaceChildren();holder.append(el('h3','',receipt.business),el('p','',words.receipt+' · '+receipt.order_no),el('p','',receipt.date||''));if(receipt.customer)holder.append(el('p','',receipt.customer));const table=el('table'),head=el('tr');for(const title of [words.item,words.quantity,words.total])head.append(el('th','',title));table.append(head);for(const item of receipt.items){const row=el('tr');row.append(el('td','',item.name),el('td','',String(item.quantity)),el('td','',money(item.total)));table.append(row);}holder.append(table);const totals=el('div','pos-totals');for(const [key,label] of [['subtotal',words.subtotal],['discount',words.discount],['tax',words.tax],['total',words.total],['paid',words.paid],['due',words.due]]){const row=el('div');row.append(el('span','',label),el('strong','',money(receipt[key])));totals.append(row);}holder.append(totals);$('pos-success').showModal();}
function nextSale(){if($('pos-success').open)$('pos-success').close();$('pos-search').focus();}
$('pos-next').onclick=nextSale;$('pos-success-close').onclick=nextSale;
$('pos-print').onclick=()=>{if(!lastReceiptUrl)return;const frame=document.createElement('iframe');frame.style.cssText='position:fixed;width:1px;height:1px;left:-10000px;top:0;border:0';frame.src=lastReceiptUrl;frame.onload=()=>{try{frame.contentWindow.addEventListener('afterprint',()=>frame.remove(),{once:true});frame.contentWindow.focus();frame.contentWindow.print();}catch(e){alertMsg(words.saleError);} };document.body.append(frame);};
form.addEventListener('submit',async e=>{
 e.preventDefault();if(!$('pos-dialog').open||!verified||submitting||$('pos-submit').disabled)return;
 if(!pendingSale){pendingSale={...snapshot(),request_key:field('request_key').value,expected_total:field('expected_total').value,payment_mode:field('payment_mode').value,payment_method:field('payment_method').value,tendered:field('tendered').value,payment_reference:field('payment_reference').value};}
 submitting=true;freezePayment(true);$('pos-submit').disabled=true;$('pos-submit').textContent=words.submitting;$('pos-pay-message').textContent='';
 try{
  const res=await fetch(form.action,{method:'POST',credentials:'same-origin',headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':field('_token').value},body:JSON.stringify(pendingSale)});
  const body=await res.json();
  if(res.status===422){pendingSale=null;freezePayment(false);throw Error(Object.values(body.errors||{}).flat()[0]||body.message||words.saleError);}
  if(!res.ok||body.success!==true||!body.request_key||!body.receipt||!body.stocks)throw Error(words.retry);
  pendingSale=null;lastReceiptUrl=body.receipt_url;field('request_key').value=body.request_key;for(const p of catalog){p.stock=Object.prototype.hasOwnProperty.call(body.stocks,String(p.id))?body.stocks[String(p.id)]:0;}
  $('pos-dialog').close();freezePayment(false);clearCart();field('payment_reference').value='';renderProducts();alertMsg('');showReceipt(body.receipt);
 }catch(err){$('pos-pay-message').textContent=pendingSale?words.retry:(err.message||words.saleError);}
 finally{submitting=false;$('pos-submit').textContent=words.confirm;if(pendingSale){$('pos-submit').disabled=false;}else if($('pos-dialog').open){const msg=$('pos-pay-message').textContent;updatePayment();if(msg)$('pos-pay-message').textContent=msg;}}
});document.addEventListener('keydown',e=>{if(e.key==='F2'&&!$('pos-dialog').open&&!$('pos-success').open){e.preventDefault();$('pos-search').focus();}if(e.key==='F8'){e.preventDefault();if(!$('pos-dialog').open&&!$('pos-success').open)checkout();}});
$('pos-product-scroll').addEventListener('scroll',()=>{const box=$('pos-product-scroll');if(box.scrollTop+box.clientHeight>=box.scrollHeight-100&&!$('pos-more').hidden){const y=box.scrollTop;limit+=96;renderProducts();box.scrollTop=y;}});renderProducts();restore({items:oldItems});const languageForm=$('pos-language');const languageKey=holdKey+'-language';languageForm?.addEventListener('submit',()=>{try{sessionStorage.setItem(languageKey,JSON.stringify(snapshot()));}catch(e){}});try{const draft=sessionStorage.getItem(languageKey);if(draft){sessionStorage.removeItem(languageKey);restore(JSON.parse(draft));}}catch(e){}
})();
</script>
